		/// <summary>
		/// Statically <b>allocate</b> and create a new <see cref="MixedStorage{T, TP1, TP2, TP3, TP4, TP5, TP6, TP7, TP8, TP9}"/> of given lengths on different locations in <see cref="IStorage.LocationDescription"/>.
		/// </summary>
